let windowSize = 30m;

// S117: BLOS Command Forgery — UAVOperator_CL(MAVLink 명령주입 감사), 비정상 결과코드의 명령
let S117 =
    UAVOperator_CL
    | where TimeGenerated > ago(windowSize)
    | where isnotnull(Command) and Result != 0
    | extend Stage = 'S117', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S118: Autonomy Hijack — 제안 스키마 전용 테이블 없음, UAVMissionEvent_CL 모드전환으로 대리 탐지
let S118 =
    UAVMissionEvent_CL
    | where TimeGenerated > ago(windowSize)
    | where CustomModeBefore != CustomModeAfter
    | extend Stage = 'S118', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

// S125: VTOL Transition Failure — UAVTelemetry_CL, 낮은 대기속도에서의 급격한 수직속도 변화
let S125 =
    UAVTelemetry_CL
    | where TimeGenerated > ago(windowSize)
    | where abs(VzDown_cms) > 500 and Airspeed_ms < 5
    | extend Stage = 'S125', UAVId = tostring(UAVId)
    | where isnotempty(UAVId)
    | project TimeGenerated, Stage, UAVId;

union S117, S118, S125
| summarize StagesSeen = make_set(Stage), StageCount = dcount(Stage), FirstSeen = min(TimeGenerated), LastSeen = max(TimeGenerated) by UAVId
| where StageCount >= 2
| extend CampaignType = "C33_자율무력_BLOS명령위조_자율하이재킹_VTOL천이실패"
| extend StepSummary = strcat("Stages=", tostring(StagesSeen), " | First=", tostring(FirstSeen), " | Last=", tostring(LastSeen))
| extend Severity = "High"
| project FirstSeen, LastSeen, UAVId, StagesSeen, StageCount, CampaignType, StepSummary, Severity
